<fieldset class="builder-field" data-builder-field><legend>Field tambahan</legend><div class="flex flex-wrap justify-end gap-2"><button type="button" class="small-button" data-field-up aria-label="Naikkan field"><x-icon name="arrow-up" class="h-3 w-3"/> Naik</button><button type="button" class="small-button" data-field-down aria-label="Turunkan field"><x-icon name="arrow-down" class="h-3 w-3"/> Turun</button><button type="button" class="small-button danger" data-field-remove><x-icon name="trash" class="h-3 w-3"/>Hapus</button></div><div class="field-grid"><div><label>Kunci stabil (bahasa Inggris)<input data-prop="key" name="fields[{{ $index }}][key]" value="{{ $field['key'] }}" required pattern="[a-z][a-z0-9_]{0,49}" placeholder="activity_name"></label></div><div><label>Label pertanyaan<input data-prop="label" name="fields[{{ $index }}][label]" value="{{ $field['label'] }}" required maxlength="150"></label></div><div><label>Jenis input<select data-prop="type" name="fields[{{ $index }}][type]">@foreach(['text'=>'Teks pendek','textarea'=>'Teks panjang','number'=>'Angka','date'=>'Tanggal','select'=>'Pilihan tunggal','multiselect'=>'Pilihan jamak','file'=>'Lampiran'] as $key=>$label)<option value="{{ $key }}" @selected($field['type']===$key)>{{ $label }}</option>@endforeach</select></label></div><div><label>Kelompok<input data-prop="group" name="fields[{{ $index }}][group]" value="{{ $field['group']??'Detail pengajuan' }}" maxlength="100"></label></div><div><label>Petunjuk<input data-prop="help" name="fields[{{ $index }}][help]" value="{{ $field['help']??'' }}" maxlength="500"></label></div><div><label>Batas karakter<input data-prop="max" type="number" name="fields[{{ $index }}][max]" min="1" max="10000" value="{{ $field['max']??2000 }}"></label></div><div class="md:col-span-2"><label>Pilihan (satu opsi per baris; untuk input pilihan)<textarea data-prop="options_text" name="fields[{{ $index }}][options_text]" rows="3">{{ $field['options_text']??implode("\n",$field['options']??[]) }}</textarea></label></div><label class="checkbox-label"><input data-prop="required" type="checkbox" name="fields[{{ $index }}][required]" value="1" @checked($field['required']??false)><span>Wajib diisi</span></label></div></fieldset>
